class FakeDashSegmentsFD(DashSegmentsFD):
    def __init__(self, params):
        self.params = params
        self.downloaded_urls = []
        self.appended_contents = []
        self.finished = False

    def _prepare_and_start_frag_download(self, ctx):
        ctx['fragment_index'] = 0

    def _download_fragment(self, ctx, url, info_dict):
        self.downloaded_urls.append(url)
        return True, b'fragdata-%d' % len(self.downloaded_urls)

    def _append_fragment(self, ctx, frag_content):
        self.appended_contents.append(frag_content)

    def _finish_frag_download(self, ctx):
        self.finished = True

    def report_retry_fragment(self, err, frag_index, count, fragment_retries):
        pass

    def report_skip_fragment(self, frag_index):
        pass

    def report_error(self, message):
        pass

